css:
.form-section.row {
    display: flex;
    flex-wrap: wrap;
    margin-bottom: 15px;
}
.form-section .col-xs-6 {
    width: 50%;
    padding: 0 10px;
    margin-bottom: 10px; /* Add some space between rows */
}
/* For better alignment of labels and values */
.form-section strong {
    display: inline-block;
    min-width: 120px; /* Adjust as needed */
}

.bank-payment-form {
    font-family: Arial, sans-serif;
    margin: 20px;
}
.bank-payment-form h1,
.bank-payment-form h2 {
    font-size: 24px;
    font-weight: bold;
    font-family: 'Times New Roman', Times, serif;
    margin-bottom: 15px;
}
.bank-payment-form hr {
    border: 0.5px solid #000;
    margin: 20px 0;
}
.bank-payment-form table {
    width: 100%;
    border-collapse: collapse;
    margin: 15px 0;
}
.bank-payment-form table, 
.bank-payment-form th, 
.bank-payment-form td {
    border: 1px solid #000;
}
.bank-payment-form th, 
.bank-payment-form td {
    padding: 8px;
    text-align: left;
}
.amount-in-words {
    margin-top: 15px;
    font-weight: bold;
}
